{
  "doc_id": "3bd0ff97c75d1a40",
  "title": "Notice SFA 03AA-N01 to the Depository on Prevention of Money Laundering and Countering the Financing of Terrorism",
  "obligations": [
    {
      "section_path": "7.3",
      "heading": "SIMPLIFIED CUSTOMER DUE DILIGENCE",
      "modality": "requirement",
      "text": "The simplified CDD measures shall be commensurate with the level of risk, based on the risk factors identified by the Depository."
    },
    {
      "section_path": "7.4",
      "heading": "SIMPLIFIED CUSTOMER DUE DILIGENCE",
      "modality": "prohibition",
      "text": "The Depository shall not perform simplified CDD measures - (a) where a customer or any beneficial owner of the customer is from or in a country or jurisdiction in relation to which the FATF has called for countermeasures; (b) where a customer or any beneficial owner of the customer is from or in a country or jurisdiction known to have inadequate AML/CFT measures, as determined by the Depository for itself, or notified to the Depository generally by the Authority, or by other foreign regulatory authorities; or (c) where the Depository suspects that money laundering or terrorism financing is involved."
    },
    {
      "section_path": "7.5",
      "heading": "SIMPLIFIED CUSTOMER DUE DILIGENCE",
      "modality": "permission",
      "text": "Subject  to  paragraphs  7.2,  7.3  and  7.4,  the  Depository  may  perform  simplified  CDD measures in relation to a customer that is a financial institution set out in Appendix 2."
    },
    {
      "section_path": "7.6",
      "heading": "SIMPLIFIED CUSTOMER DUE DILIGENCE",
      "modality": "requirement",
      "text": "Where the Depository performs simplified CDD measures in relation to a customer, any natural person appointed to act on behalf of the customer and any beneficial owner of the customer, it shall document - (a) the details of its risk assessment; and (b) the nature of the simplified CDD measures."
    },
    {
      "section_path": "8.2",
      "heading": null,
      "modality": "requirement",
      "text": "The Depository shall implement appropriate internal risk management systems, policies, procedures and controls to determine if a customer, any natural person appointed to act on behalf of the customer, any connected party of the customer or any beneficial owner of the customer is a politically exposed person, or a family member or close associate of a politically exposed person."
    },
    {
      "section_path": "8.3",
      "heading": null,
      "modality": "requirement",
      "text": "The Depository shall, in addition to performing CDD measures (specified in paragraph 6), perform  at  least  the  following  enhanced  CDD  measures  where  a  customer  or  any beneficial  owner  of  the  customer  is  determined  by  the  Depository  to  be  a  politically exposed person, or a family member or close associate of a politically exposed person under paragraph 8.2: (a) obtain approval from the Depository's senior management to establish or continue business relations with the customer; (b) establish, by appropriate and reasonable means, the source of wealth and source of funds of the customer and any beneficial owner of the customer; and (c) conduct, during the course of business relations with the customer, enhanced monitoring of business relations with the customer."
    },
    {
      "section_path": "8.3",
      "heading": null,
      "modality": "requirement",
      "text": "In particular, the Depository shall increase the degree and nature of monitoring of the business relations with, and transfers undertaken in the course of business relations with, the customer, in order to determine whether they appear unusual or suspicious."
    },
    {
      "section_path": "8.4",
      "heading": null,
      "modality": "permission",
      "text": "The  Depository  may  adopt  a  risk-based  approach  in  determining  whether  to  perform enhanced CDD measures or the extent of enhanced CDD measures to be performed for - (a) domestic politically exposed persons, their family members and close associates; (b) international organisation politically exposed persons, their family members and close associates; or (c) politically exposed persons who have stepped down from their prominent public functions,  taking  into  consideration  the  level  of  influence  such  persons  may continue to exercise after stepping down from their prominent public functions, their family members and close associates, except in cases where their business relations or transfers with the Depository present a higher risk for money laundering or terrorism financing."
    },
    {
      "section_path": "8.5",
      "heading": null,
      "modality": "requirement",
      "text": "The Depository shall implement appropriate internal risk management systems, policies, procedures and controls to determine if business relations with, or transfers undertaken in the course of business relations with, any customer present a higher risk for money laundering or terrorism financing."
    },
    {
      "section_path": "8.6",
      "heading": null,
      "modality": "requirement",
      "text": "For the purposes of paragraph 8.5, circumstances where a customer presents or may present  a  higher  risk  for  money  laundering  or  terrorism  financing  include  but  are  not limited to the following: (a) where a customer or any beneficial owner of the customer is from or in a country or jurisdiction in relation to which the FATF has called for countermeasures , the Depository shall treat any business relations with or transfers undertaken in the course of business relations for any such customer as presenting a higher risk for money laundering or terrorism financing; (b) where a customer or any beneficial owner of the customer is from or in a country or jurisdiction known to have inadequate AML/CFT measures, as determined by the Depository for itself, or notified to the Depository generally by the Authority or other foreign regulatory authorities, the Depository shall assess whether any such customer presents a higher risk for money laundering or terrorism financing; and (c) where  a  customer  is  a  legal  person  for  which  the  Depository  is  not  able  to establish if it has any - (i) ongoing, apparent or visible operation or business activity; (ii) economic or business purpose for its corporate structure or arrangement; or (iii) substantive financial activity in its interactions with the Depository, the Depository shall assess whether any such customer presents a higher risk for money laundering or terrorism financing."
    },
    {
      "section_path": "8.7",
      "heading": null,
      "modality": "requirement",
      "text": "The Depository shall perform the appropriate enhanced CDD measures in paragraph 8.3 for business relations with or transfers undertaken in the course of business relations for any customer - (a) who the Depository determines under paragraph 8.5; or (b) the Authority or other relevant authorities in Singapore notify to the Depository, as presenting a higher risk for money laundering or terrorism financing."
    },
    {
      "section_path": "8.8",
      "heading": null,
      "modality": "requirement",
      "text": "The Depository shall, in taking enhanced CDD measures to manage and mitigate any higher risks that have been identified by the Depository, or notified to it by the Authority or other relevant authorities in Singapore, ensure that the enhanced CDD measures take into account the requirements of any laws, regulations or directions administered by the Authority, including but not limited to the regulations or directions issued by the Authority under section 192 read with section 15(1)(b) of the FSM Act, and section 15(1)(a) of the FSM Act respectively."
    },
    {
      "section_path": "9.2",
      "heading": "RELIANCE ON THIRD PARTIES",
      "modality": "permission",
      "text": "Subject  to  paragraph  9.3,  the  Depository  may  rely  on  a  third  party  to  perform  the measures as required by paragraphs 6, 7 and 8 if the following requirements are met: (a) the Depository is satisfied that the third party it intends to rely upon is subject to and  supervised  for  compliance  with  AML/CFT  requirements  consistent  with standards set by the FATF, and has adequate AML/CFT measures in place to comply with those requirements; (b) the  Depository takes appropriate steps to identify, assess and understand the money  laundering  and  terrorism  financing  risks  particular  to  the  countries  or jurisdictions that the third party operates in; (c) the third party is not one which the Depository has been specifically precluded by the Authority from relying upon; and (d) the third party is able and willing to provide, without delay, upon the Depository's request,  any  data,  documents  or  information  obtained  by  the  third  party  with respect  to  the  measures  applied  on  the  Depository's  customer,  which  the Depository would be required or would want to obtain."
    },
    {
      "section_path": "9.3",
      "heading": "RELIANCE ON THIRD PARTIES",
      "modality": "prohibition",
      "text": "The Depository shall not rely on a third party to conduct ongoing monitoring of business relations with customers."
    },
    {
      "section_path": "9.4",
      "heading": "RELIANCE ON THIRD PARTIES",
      "modality": "requirement",
      "text": "Where the Depository relies on a third party to perform the measures as required by paragraphs 6, 7 and 8, it shall - (a) document the basis for its satisfaction that the requirements in paragraphs 9.2(a) and (b) have been met, except where the third party is a financial institution set out in Appendix 2; and (b) immediately obtain from the third party the CDD information which the third party had obtained."
    },
    {
      "section_path": "9.5",
      "heading": "RELIANCE ON THIRD PARTIES",
      "modality": "requirement",
      "text": "For  the  avoidance  of  doubt,  notwithstanding  the  reliance  upon  a  third  party,  the Depository shall remain responsible for its AML/CFT obligations in this Notice."
    },
    {
      "section_path": "10.3",
      "heading": "CORRESPONDENT ACCOUNTS",
      "modality": "requirement",
      "text": "The Depository shall perform the following measures, in addition to the measures as required by paragraphs 6, 7 and 8, when providing correspondent account services: (a) assess the suitability of the respondent financial institution by taking the following steps: (i) gather adequate information about the respondent financial institution to understand  fully  the  nature  of  the  respondent  financial  institution's business, including making appropriate inquiries on its management, its major  business  activities  and  the  countries  or  jurisdictions  in  which  it operates; (ii) determine from any available sources the reputation of the respondent financial  institution  and  the  quality  of  supervision  over  the  respondent financial institution, including whether it has been the subject of money laundering or terrorism financing investigation or regulatory action; and (iii) assess  the  respondent  financial  institution's  AML/CFT  controls  and ascertain  that  they  are  adequate  and  effective,  having  regard  to  the AML/CFT measures of the country or jurisdiction in which the respondent financial institution operates; (b) clearly  understand  and  document  the  respective  AML/CFT  responsibilities  of each financial institution; and (c) obtain  approval  from  the  Depository's  senior  management  before  providing correspondent account services to a new financial institution."
    },
    {
      "section_path": "10.4",
      "heading": "CORRESPONDENT ACCOUNTS",
      "modality": "requirement",
      "text": "Where  the  correspondent  account  services  involve  a  payable-through  account,  the Depository shall be satisfied that - (a) the respondent financial institution has performed appropriate measures at least equivalent to those specified in paragraph 6 on the third party having direct access to the payable-through account; and (b) the respondent financial institution is able to perform ongoing monitoring of its business relations with that third party and is willing and able to provide CDD information to the Depository upon request."
    },
    {
      "section_path": "10.5",
      "heading": "CORRESPONDENT ACCOUNTS",
      "modality": "requirement",
      "text": "The  Depository  shall  document  the  basis  for  its  satisfaction  that  the  requirements  in paragraphs 10.3 and 10.4 are met."
    },
    {
      "section_path": "10.6",
      "heading": "CORRESPONDENT ACCOUNTS",
      "modality": "prohibition",
      "text": "The  Depository  shall  not  enter  into  or  continue  correspondent  account  relations  with another  financial  institution  that  does  not  have  adequate  controls  against  money laundering or terrorism financing activities, is not effectively supervised by the relevant authorities, or is a shell financial institution."
    },
    {
      "section_path": "10.7",
      "heading": "CORRESPONDENT ACCOUNTS",
      "modality": "requirement",
      "text": "The Depository shall also take appropriate measures when establishing correspondent account services relationship, to satisfy itself that its respondent financial institutions do not permit their accounts to be used by shell financial institutions."
    },
    {
      "section_path": "11.1",
      "heading": "RECORD KEEPING",
      "modality": "requirement",
      "text": "The  Depository  shall,  in  relation  to  all  data,  documents  and  information  that  the Depository is required to obtain or produce to meet the requirements under this Notice, prepare, maintain and retain records of such data, documents and information."
    },
    {
      "section_path": "11.2",
      "heading": "RECORD KEEPING",
      "modality": "requirement",
      "text": "The Depository shall perform the measures as required by paragraph 11.1 such that - (a) all requirements imposed by law (including this Notice) are met; (b) any  individual  transfer  undertaken  by  the  Depository  can  be  reconstructed (including  the  amounts  and  types  of  currency  involved)  so  as  to  provide,  if necessary, evidence for prosecution of criminal activity; (c) the  Authority  or  other  relevant  authorities  in  Singapore  and  the  internal  and external auditors of the Depository are able to review the Depository's business relations, transfers undertaken in the course of business relations, records and CDD information and assess the level of compliance with this Notice; and (d) the Depository can satisfy, within a reasonable time or any more specific time period imposed by law or by the requesting authority, any enquiry or order from the relevant authorities in Singapore for information."
    },
    {
      "section_path": "11.3",
      "heading": "RECORD KEEPING",
      "modality": "requirement",
      "text": "Subject to paragraph 11.5 and any other requirements imposed by law, the Depository shall, for the purposes of record retention under paragraphs 11.1 and 11.2, and when setting its record retention policies, comply with the following record retention periods: (a) for CDD information relating to the business relations, as well as account files, business correspondence and results of any analysis undertaken, a period of at least 5 years following the termination of such business relations; and (b) for  data,  documents  and  information  relating  to  a  transfer  undertaken  in  the course of  business relations,  including  any  information  needed  to  explain  and reconstruct the transfer, a period of at least 5 years following the completion of the transfer."
    },
    {
      "section_path": "11.4",
      "heading": "RECORD KEEPING",
      "modality": "permission",
      "text": "The Depository may retain data, documents and information as originals or copies, in paper or electronic form or on microfilm, provided that they are admissible as evidence in a Singapore court of law."
    },
    {
      "section_path": "11.5",
      "heading": "RECORD KEEPING",
      "modality": "requirement",
      "text": "The Depository shall retain records of data, documents and information on all its business relations with or transfers undertaken in the course of business relations for a customer pertaining to a matter which is under investigation or which has been the subject of an STR, in accordance with any request or order from STRO or other relevant authorities in Singapore."
    },
    {
      "section_path": "12.2",
      "heading": "PERSONAL DATA",
      "modality": "prohibition",
      "text": "Subject  to  paragraph  12.3  and  for  the  purposes  of  complying  with  this  Notice,  the Depository  shall  not  be  required  to  provide  an  individual  customer,  an  individual appointed to act on behalf of a customer, an individual connected party of a customer or an individual beneficial owner of a customer, with - (a) any access to personal data about the individual that is in the possession or under the control of the Depository; (b) any information about the ways in which the personal data of the individual under subparagraph  (a)  has  been  or  may  have  been  used  or  disclosed  by  the Depository; and (c) any right to correct an error or omission of the personal data about the individual that is in the possession or under the control of the Depository."
    },
    {
      "section_path": "12.3",
      "heading": "PERSONAL DATA",
      "modality": "requirement",
      "text": "The Depository shall, as soon as reasonably practicable, upon the request of an individual customer, an individual appointed to act on behalf of a customer, an individual connected party of a customer or an individual beneficial owner of a customer, provide the requesting individual with the right to - (a) access  the  following  types  of  personal  data  of  that  individual,  that  is  in  the possession or under the control of the Depository: (i) the individual's full name, including any alias; (ii) the  individual's unique  identification  number  (such  as  an  identity  card number, birth certificate number or passport number); (iii) the individual's residential address; (iv) the individual's date of birth; (v) the individual's nationality; (vi) subject  to  sections  21(2)  and  (3)  read  with  the  Fifth  Schedule  to  the Personal  Data  Protection  Act  2012,  any  other  personal  data  of  the respective individual provided by that individual to the Depository; and (b) subject  to  section  22(7)  read  with  the  Sixth  Schedule  to  the  Personal  Data Protection  Act  2012,  correct  an  error  or  omission  in  relation  to  the  types  of personal data set out in subparagraphs (a)(i) to (vi), provided the Depository is satisfied that there are reasonable grounds for such request."
    },
    {
      "section_path": "12.4",
      "heading": "PERSONAL DATA",
      "modality": "permission",
      "text": "For the purposes of complying with this Notice, the Depository may, whether directly or through a third party, collect, use and disclose personal data of an individual customer, an individual appointed to act on behalf of a customer, an individual connected party of a customer  or  an  individual  beneficial  owner  of  a  customer,  without  the  respective individual's consent."
    },
    {
      "section_path": "13.1",
      "heading": "SUSPICIOUS TRANSACTIONS REPORTING",
      "modality": "requirement",
      "text": "The Depository shall keep in mind the provisions in the CDSA 6  and in the TSOFA that provide for the reporting to the authorities of transactions suspected of being connected with money laundering or terrorism financing and implement appropriate internal policies, procedures and controls for meeting its obligations under the law, including the following: (a) establish a single reference point within the organisation to whom all employees and officers are instructed to promptly refer all transfers undertaken in the course of  business  relations  suspected  of  being  connected  with  money  laundering  or terrorism financing, for possible referral to STRO via STRs; and (b) keep records of all transfers referred to STRO, together with all internal findings and analysis done in relation to them."
    },
    {
      "section_path": "13.2",
      "heading": "SUSPICIOUS TRANSACTIONS REPORTING",
      "modality": "requirement",
      "text": "The Depository shall promptly submit reports on suspicious transfers undertaken in the course of business relations (including attempted transfers), regardless of the amount of the transfer, to STRO, and extend a copy to the Authority upon request."
    },
    {
      "section_path": "13.3",
      "heading": "SUSPICIOUS TRANSACTIONS REPORTING",
      "modality": "requirement",
      "text": "The Depository shall consider if the circumstances are suspicious so as to warrant the filing of an STR and document the basis for its determination, including where - 6  Please note in particular section 57 of the CDSA on tipping-off. (a) the Depository is for any reason unable to complete the measures as required by paragraphs 6, 7 and 8; or (b) the customer is reluctant, unable or unwilling to provide any information requested by  the  Depository,  or  decides  to  withdraw  a  pending  application  to  establish business  relations  or  a  pending  transfer  to  be  undertaken  in  the  course  of business relations, or to terminate existing business relations."
    },
    {
      "section_path": "13.4",
      "heading": "SUSPICIOUS TRANSACTIONS REPORTING",
      "modality": "requirement",
      "text": "Where the Depository forms a suspicion of money laundering or terrorism financing, and reasonably believes that performing any of the measures as required by paragraphs 6, 7 or 8 will tip-off a customer, a natural person appointed to act on behalf of the customer or a connected party of the customer, or a beneficial owner of the customer, the Depository may stop performing those measures, shall document the basis for its assessment and file an STR."
    },
    {
      "section_path": "14.1",
      "heading": "INTERNAL POLICIES, COMPLIANCE, AUDIT AND TRAINING",
      "modality": "requirement",
      "text": "The Depository shall develop and implement adequate internal policies, procedures and controls, taking into consideration its money laundering and terrorism financing risks and the size of its business, to help prevent money laundering and terrorism financing and communicate these to its employees."
    },
    {
      "section_path": "14.2",
      "heading": "INTERNAL POLICIES, COMPLIANCE, AUDIT AND TRAINING",
      "modality": "requirement",
      "text": "The policies, procedures and controls shall meet all the requirements of this Notice."
    },
    {
      "section_path": "14.3",
      "heading": null,
      "modality": "requirement",
      "text": "The  Depository  shall  develop  appropriate  compliance  management  arrangements, including at least, the appointment of an AML/CFT compliance officer at the management level."
    },
    {
      "section_path": "14.4",
      "heading": null,
      "modality": "requirement",
      "text": "The Depository shall ensure that the AML/CFT compliance officer, as well as any other persons appointed to assist the AML/CFT compliance officer, is suitably qualified, and has adequate resources and timely access to all customer records and other relevant information which the AML/CFT compliance officer requires to discharge the AML/CFT compliance officer's functions."
    },
    {
      "section_path": "14.5",
      "heading": null,
      "modality": "requirement",
      "text": "The  Depository  shall  maintain  an  audit  function  that  is  adequately  resourced  and independent, and that is able to regularly assess the effectiveness of the Depository's internal policies, procedures and controls, and its compliance with regulatory requirements."
    },
    {
      "section_path": "14.6",
      "heading": null,
      "modality": "requirement",
      "text": "The Depository shall have in place screening procedures to ensure high standards when hiring employees and appointing officers."
    },
    {
      "section_path": "14.7",
      "heading": null,
      "modality": "requirement",
      "text": "The Depository shall take all appropriate steps to ensure that its employees and officers are regularly and appropriately trained on - (a) AML/CFT laws and regulations, and in particular, CDD measures, and detecting and reporting of suspicious transfers; (b) prevailing  techniques,  methods  and  trends  in  money  laundering  and  terrorism financing; and (c) the  Depository's  internal AML/CFT policies,  procedures  and  controls,  and  the roles and responsibilities of employees, officers and representatives in combating money laundering and terrorism financing."
    }
