{
  "doc_id": "3b3ee4828e1084c8",
  "title": "PSN01A Prevention of Money Laundering and Countering the Financing of Terrorism - Persons Providing Account Issuances Services who are Exempted under the Payment Services (Exemption for Specified Period) Regulations 2019",
  "obligations": [
    {
      "section_path": "6.38",
      "heading": null,
      "modality": "requirement",
      "text": "An exempt person shall screen a customer, natural persons appointed to act on behalf of the customer, connected parties of the customer and beneficial owners of the customer against relevant money laundering and terrorism financing information sources, as well as  lists  and  information  provided  by  the  Authority  or  other  relevant  authorities  in Singapore for the purposes of determining if there are any money laundering or terrorism financing risks in relation to the customer."
    },
    {
      "section_path": "6.39",
      "heading": null,
      "modality": "requirement",
      "text": "An exempt person shall screen the persons referred to in paragraph 6.38  (a) when, or as soon as reasonably practicable after, the exempt person establishes business relations with a customer; (aa) when  the  exempt  person  undertakes  any  transaction  of  a  value  exceeding S$5,000 for any customer who has not otherwise established business relations with the exempd person; (b) on a periodic basis after the exempt person establishes business relations with the customer; and (c) when there are any changes or updates to  (i) the  lists  and  information  provided  by  the  Authority  or  other  relevant authorities in Singapore to the exempt person; or (ii) the natural persons appointed to act on behalf of a customer, connected parties of a customer or beneficial owners of a customer."
    },
    {
      "section_path": "6.40",
      "heading": null,
      "modality": "requirement",
      "text": "The results of screening and assessment by the exempt person shall be documented."
    },
    {
      "section_path": "7.1",
      "heading": "SIMPLIFIED CUSTOMER DUE DILIGENCE",
      "modality": "permission",
      "text": "Subject to paragraph 7.4, an exempt person may perform simplified CDD measures in relation to a customer, any natural person appointed to act on behalf of the customer and any beneficial owner of the customer (other than any beneficial owner that the exempt person is exempted from making inquiries about under paragraph 6.16) if it is satisfied that the risks of money laundering and terrorism financing are low."
    },
    {
      "section_path": "7.2",
      "heading": "SIMPLIFIED CUSTOMER DUE DILIGENCE",
      "modality": "requirement",
      "text": "The assessment of low risks shall be supported by an adequate analysis of risks by the exempt person."
    },
    {
      "section_path": "7.3",
      "heading": "SIMPLIFIED CUSTOMER DUE DILIGENCE",
      "modality": "requirement",
      "text": "The simplified CDD measures shall be commensurate with the level of risk, based on the risk factors identified by the exempt person."
    },
    {
      "section_path": "7.4",
      "heading": "SIMPLIFIED CUSTOMER DUE DILIGENCE",
      "modality": "prohibition",
      "text": "An exempt person shall not perform simplified CDD measures  (a) where one or more transactions undertaken, whether in the course of business relations  or  otherwise,  by  the  exempt  person  for  a  customer  (other  than transactions  undertaken  by  the  exempt  person  to  transfer  funds  from  the customer's relevant stored value facility directly to that customer's bank account) in any one year period cumulatively exceeds S$5,000 4 ; (b) where a customer or any beneficial owner of the customer is from or in a country or jurisdiction in relation to which the FATF has called for countermeasures; 4 Please note paragraph 6.4 of the Notice. (c) where a customer or any beneficial owner of the customer is from or in a country or jurisdiction known to have inadequate AML/CFT measures, as determined by the  exempt  person  for  itself  or  notified  to  exempt  persons  generally  by  the Authority, or other foreign regulatory authorities; or (d) where the exempt person suspects that money laundering or terrorism financing is involved."
    },
    {
      "section_path": "7.5",
      "heading": "SIMPLIFIED CUSTOMER DUE DILIGENCE",
      "modality": "prohibition",
      "text": "A transaction undertaken, whether in the course of business relations or otherwise, by the  exempt  person  to  transfer  funds  from  a  customer's  relevant  stored  value  facility directly to that customer's bank account shall not be a transaction for the purposes of paragraph 7.4(a), if that the bank account is not opened or maintained in a country or jurisdiction known to have inadequate AML/CFT measures (as determined by the exempt person for  itself  or  notified  to  exempt  persons  generally  by  the Authority  or  by  other foreign regulatory authorities)."
    },
    {
      "section_path": "7.6",
      "heading": "SIMPLIFIED CUSTOMER DUE DILIGENCE",
      "modality": "permission",
      "text": "Subject to paragraphs 7.2, 7.3 and 7.4, an exempt person may perform simplified CDD measures in relation to a customer that is a financial institution set out in Appendix 2."
    },
    {
      "section_path": "7.7",
      "heading": "SIMPLIFIED CUSTOMER DUE DILIGENCE",
      "modality": "requirement",
      "text": "Where the exempt person performs simplified CDD measures in relation to a customer, any natural person appointed to act on behalf of the customer and any beneficial owner of the customer, it shall document  (a) the details of its risk assessment; and (b) the nature of the simplified CDD measures."
    },
    {
      "section_path": "8.2",
      "heading": null,
      "modality": "requirement",
      "text": "An  exempt  person  shall  implement  appropriate  internal  risk  management  systems, policies,  procedures  and  controls  to  determine  if  a  customer,  any  natural  person appointed to act on behalf of the customer, any connected party of the customer or any beneficial owner of the customer is a politically exposed person, or a family member or close associate of a politically exposed person."
    },
    {
      "section_path": "8.3",
      "heading": null,
      "modality": "requirement",
      "text": "An  exempt person shall, in addition to performing CDD measures (specified in paragraph 6),  perform at least the following enhanced CDD  measures where a customer or any beneficial owner of the customer is determined by the  exempt person to be a politically exposed person, or a family member or close associate of a politically exposed person under paragraph 8.2: (a) obtain approval from the  exempt person's senior management to establish or continue business relations with the customer; (b) establish, by appropriate and reasonable means, the source of wealth and source of funds of the customer and any beneficial owner of the customer; and (c) conduct, during the course of business relations with the customer, enhanced monitoring of the business relations with the customer."
    },
    {
      "section_path": "8.3",
      "heading": null,
      "modality": "requirement",
      "text": "In particular, the  exempt person  shall  increase  the  degree  and  nature  of  monitoring  of  the  business relations with and transactions for the customer, in order to determine whether they appear unusual or suspicious."
    },
    {
      "section_path": "8.4",
      "heading": null,
      "modality": "permission",
      "text": "An  exempt person may adopt a risk-based approach in determining whether to perform enhanced CDD measures or the extent of enhanced CDD measures to be performed for  (a) domestic politically exposed persons, their family members and close associates; (b) international organisation politically exposed persons, their family members and close associates; or (c) politically exposed persons who have stepped down from their prominent public functions,  taking  into  consideration  the  level  of  influence  such  persons  may continue to exercise after stepping down from their prominent public functions, their family members and close associates, except in cases where their business relations or transactions with the  exempt person present a higher risk for money laundering or terrorism financing."
    },
    {
      "section_path": "8.5",
      "heading": null,
      "modality": "requirement",
      "text": "An  exempt  person  shall  implement  appropriate  internal  risk  management  systems, policies, procedures and controls to determine if business relations with or transactions for any customer present a higher risk for money laundering or terrorism financing."
    },
    {
      "section_path": "8.6",
      "heading": null,
      "modality": "requirement",
      "text": "For the purposes of paragraph 8.5, circumstances where a customer presents or may present a higher risk  for  money  laundering  or  terrorism  financing  include  but  are  not limited to the following: (a) where a customer or any beneficial owner of the customer is from or in a country or jurisdiction in relation to which the FATF has called for countermeasures, the exempt person shall treat any business relations with or transactions for any such customer as presenting a higher risk for money laundering or terrorism financing; and (b) where a customer or any beneficial owner of the customer is from or in a country or jurisdiction known to have inadequate AML/CFT measures, as determined by the  exempt  person  for  itself  or  notified  to  exempt  persons  generally  by  the Authority or other foreign regulatory authorities, the exempt person shall assess whether  any  such  customer  presents  a  higher  risk  for  money  laundering  or terrorism financing."
    },
    {
      "section_path": "8.7",
      "heading": null,
      "modality": "requirement",
      "text": "An exempt person shall perform the appropriate enhanced CDD measures in paragraph 8.3 for business relations with, or transactions for, any customer  (a) who the exempt person determines under paragraph 8.5; or (b) the  Authority  or  other  relevant  authorities  in  Singapore  notify  to  the  exempt person, as presenting a higher risk for money laundering or terrorism financing."
    },
    {
      "section_path": "8.8",
      "heading": null,
      "modality": "requirement",
      "text": "An exempt person shall, in taking enhanced CDD measures to manage and mitigate any higher risks that have been identified by the exempt person or notified to it by the Authority or other relevant authorities in Singapore, ensure that the enhanced CDD measures take into account the requirements of any laws, regulations or directions administered by the Authority, including but not limited to the regulations or directions issued by the Authority under section 27A of the MAS Act."
    },
    {
      "section_path": "9.1",
      "heading": "RELIANCE ON THIRD PARTIES",
      "modality": "permission",
      "text": "For the purposes of paragraph 9, 'third party' means  (a) a financial institution set out in Appendix 2; or (b) a financial institution which is subject to and supervised by a foreign authority for compliance  with  AML/CFT  requirements  consistent  with  standards  set  by  the FATF (other than a holder of a payment services licence that entitles the person to carry on a business of providing a money changing service or a cross-border money transfer service, or both, who are holders of a money-changer's licence or a remittance licence (as the case may be) immediately before the appointed date, or equivalent licences)."
    },
    {
      "section_path": "9.2",
      "heading": "RELIANCE ON THIRD PARTIES",
      "modality": "permission",
      "text": "Subject to paragraph 9.3, an exempt person may rely on a third party to perform the measures as required by paragraphs 6, 7 and 8 if the following requirements are met: (a) the exempt person is satisfied that the third party it intends to rely upon is subject to  and supervised for compliance with AML/CFT requirements consistent with standards set by the FATF, and has adequate AML/CFT measures in place to comply with those requirements; (b) the exempt person takes appropriate steps to identify, assess and understand the money laundering and terrorism financing risks particular to the countries or jurisdictions that the third party operates in; (c) the third party is not one which exempt persons have been specifically precluded by the Authority from relying upon; and (d) the  third  party  is  able  and  willing  to  provide,  without  delay,  upon  the  exempt person's request, any data, documents or information obtained by the third party with respect to the measures applied on the exempt person's customer, which the exempt person would be required or would want to obtain."
    },
    {
      "section_path": "9.3",
      "heading": "RELIANCE ON THIRD PARTIES",
      "modality": "requirement",
      "text": "No exempt person shall rely on a third party to conduct ongoing monitoring of business relations with customers."
    },
    {
      "section_path": "9.4",
      "heading": "RELIANCE ON THIRD PARTIES",
      "modality": "requirement",
      "text": "Where an exempt person relies on a third party to perform the measures as required by paragraphs 6, 7 and 8, it shall  (a) document the basis for its satisfaction that the requirements in paragraph 9.2(a)  and  (b)  have  been  met,  except  where  the  third  party  is  a  financial institution set out in Appendix 2; and (b) immediately obtain from the third party the CDD information which the third party had obtained."
    },
    {
      "section_path": "9.5",
      "heading": "RELIANCE ON THIRD PARTIES",
      "modality": "requirement",
      "text": "For the avoidance of doubt, notwithstanding the reliance upon a third party, the exempt person shall remain responsible for its AML/CFT obligations in this Notice."
    },
    {
      "section_path": "10.3",
      "heading": "CORRESPONDENT ACCOUNTS",
      "modality": "requirement",
      "text": "An exempt person in Singapore shall perform the following measures, in addition to the measures as required by paragraphs 6,7 and 8, when providing correspondent account services or other similar services  (a) assess the suitability of the respondent financial institution by taking the following steps  (i) gather adequate information about the respondent financial institution to understand  fully  the  nature  of  the  respondent  financial  institution's business, including making appropriate inquiries on its management, its major  business  activities  and  the  countries  or  jurisdictions  in  which  it operates; (ii) determine from any available sources the reputation of the respondent financial  institution  and  the  quality  of  supervision over  the  respondent financial institution, including whether it has been the subject of money laundering or terrorism financing investigation or regulatory action; and (iii) assess  the  respondent  financial  institution's  AML/CFT  controls  and ascertain  that  they  are  adequate  and  effective,  having  regard  to  the AML/CFT measures of the country or jurisdiction in which the respondent financial institution operates; (b) clearly understand and document the respective AML/CFT responsibilities of the exempt person and the respondent financial institution; and (c) obtain approval from the exempt person's senior management before providing correspondent account services or similar services to a new financial institution."
    },
    {
      "section_path": "10.4",
      "heading": "CORRESPONDENT ACCOUNTS",
      "modality": "requirement",
      "text": "Where the provision of correspondent account services or similar services by the exempt person involve a payable-through account, the exempt person shall be satisfied that  (a) the respondent financial institution has performed appropriate measures at least equivalent  to  those  specified  in  paragraph  6  on  the  third  party  having  direct access to the payable-through account; and (b) the respondent financial institution is able to perform ongoing monitoring of its business relations with that third party and is willing and able to provide CDD information to the exempt person upon request."
    },
    {
      "section_path": "10.5",
      "heading": "CORRESPONDENT ACCOUNTS",
      "modality": "requirement",
      "text": "The exempt person shall document the basis for its satisfaction that the requirements in paragraphs 10.3 and 10.4 are met."
    },
    {
      "section_path": "10.6",
      "heading": "CORRESPONDENT ACCOUNTS",
      "modality": "requirement",
      "text": "No exempt person shall enter into or continue correspondent account services or other similar services relationship with another financial institution that does not have adequate controls  against  money  laundering  or  terrorism  financing  activities,  is  not  effectively supervised by the relevant authorities or is a shell financial institution."
    },
    {
      "section_path": "10.7",
      "heading": "CORRESPONDENT ACCOUNTS",
      "modality": "requirement",
      "text": "An exempt person shall also take appropriate measures when establishing correspondent account services or other similar services relationship, to satisfy itself that its  respondent  financial  institutions  do  not  permit  their  accounts  to  be  used  by  shell financial institutions."
    },
    {
      "section_path": "11.1",
      "heading": "RECORD KEEPING",
      "modality": "requirement",
      "text": "An exempt person shall, in relation to all data, documents and information that the exempt person  is  required  to  obtain  or  produce  to  meet  the  requirements  under  this  Notice, prepare, maintain and retain records of such data, documents and information."
    },
    {
      "section_path": "11.2",
      "heading": "RECORD KEEPING",
      "modality": "requirement",
      "text": "An exempt person shall perform the measures as required by paragraph 11.1 such that  (a) all requirements imposed by law (including this Notice) are met; (b) any  individual  transaction  undertaken  by  the  exempt  person  in  the  course  of business  relations  can  be  reconstructed  (including  the  amount  and  type  of currency involved) so as to provide, if necessary,  evidence for prosecution of criminal activity; (c) the  Authority  or  other  relevant  authorities  in  Singapore  and  the  internal  and external auditors of the exempt person are able to review the exempt person's business relations, transactions, records and CDD information and assess the level of compliance with this Notice; and (d) the exempt person can satisfy, within a reasonable time or any more specific time period imposed by law or by the requesting authority, any enquiry or order from the relevant authorities in Singapore for information."
    },
    {
      "section_path": "11.3",
      "heading": "RECORD KEEPING",
      "modality": "requirement",
      "text": "Subject to paragraph 11.5 and any other requirements imposed by law, an exempt person shall, for the purposes of record retention under paragraphs 11.1 and 11.2 and when setting its record retention policies, comply with the following record retention periods: (a) for  CDD information relating to the business relations, transactions as well as account files, business correspondence and results of any analysis undertaken, a period of at least 5 years following the termination of such business relations or completion of such transactions; and (b) for  data,  documents  and  information  relating  to  a  transaction,  including  any information needed to explain and reconstruct the transaction, a period of at least 5 years following the completion of the transaction."
    },
    {
      "section_path": "11.4",
      "heading": "RECORD KEEPING",
      "modality": "permission",
      "text": "An exempt person may retain data, documents and information as originals or copies, in paper or electronic form or on microfilm, provided that they are admissible as evidence in a Singapore court of law."
    },
    {
      "section_path": "11.5",
      "heading": "RECORD KEEPING",
      "modality": "requirement",
      "text": "An exempt person shall retain records of data, documents and information on all its business relations with or transactions for a customer pertaining to a matter which is under investigation or which has been the subject of an STR, in accordance with any request or order from STRO or other relevant authorities in Singapore."
    },
    {
      "section_path": "12.2",
      "heading": "PERSONAL DATA",
      "modality": "prohibition",
      "text": "Subject to paragraph 12.3 and for the purposes of complying with this Notice, an exempt person shall not be required to provide an individual customer, an individual appointed to act on behalf of a customer, an individual connected party of a customer or an individual beneficial owner of a customer, with  (a) any access to personal data about the individual that is in the possession or under the control of the exempt person; (b) any information about the ways in which the personal data of the individual under subparagraph (a) has been or may have been used or disclosed by the exempt person; and (c) any right to correct an error or omission of the personal data about the individual that is in the possession or under the control of the exempt person."
    },
    {
      "section_path": "12.3",
      "heading": "PERSONAL DATA",
      "modality": "requirement",
      "text": "An  exempt  person  shall,  as  soon  as  reasonably  practicable,  upon  the  request  of  an individual customer, an individual appointed to act on behalf of a customer, an individual connected party of a customer or an individual beneficial owner of a customer, provide the requesting individual with the right to  (a) access  the  following  types  of  personal  data  of  that  individual,  that  is  in  the possession or under the control of the exempt person: (i) his full name, including any alias; (ii) his unique identification number (such as an identity card number, birth certificate number or passport number); (iii) his residential address; (iv) his date of birth; (v) his nationality; (vi) subject  to  section  21(2)  and  (3)  read  with  the  Fifth  Schedule  to  the Personal Data Protection Act 2012 (Act 26 of 2012), any other personal data of the respective individual provided by that individual to the exempt person; and (b) subject  to  section  22(7)  read  with  the  Sixth  Schedule  to  the  Personal  Data Protection Act, correct an error or omission in relation to the types of personal data set out in subparagraphs (a)(i) to (vi), provided the exempt person is satisfied that there are reasonable grounds for such request."
    },
    {
      "section_path": "12.4",
      "heading": "PERSONAL DATA",
      "modality": "permission",
      "text": "For the purposes of complying with this Notice, an exempt person may, whether directly or through a third party, collect, use and disclose personal data of an individual customer, an individual appointed to act on behalf of a customer, an individual connected party of a customer  or  an  individual  beneficial  owner  of  a  customer,  without  the  respective individual's consent."
    },
    {
      "section_path": "13.1",
      "heading": "SUSPICIOUS TRANSACTIONS REPORTING",
      "modality": "requirement",
      "text": "An exempt person shall keep in mind the provisions in the CDSA 5  and in the TSOFA that provide for the reporting to the authorities of transactions suspected of being connected with money laundering or terrorism financing and implement appropriate internal policies, procedures and controls for meeting its obligations under the law, including the following  (a) establish a single reference point within the organisation to whom all employees and officers are instructed to promptly refer all transactions suspected of being connected with money laundering or terrorism financing, for possible referral to STRO via STRs; and (b) keep  records  of  all  transactions  referred  to  STRO,  together  with  all  internal findings and analysis done in relation to them."
    },
    {
      "section_path": "13.2",
      "heading": "SUSPICIOUS TRANSACTIONS REPORTING",
      "modality": "requirement",
      "text": "An exempt person shall promptly submit reports on suspicious transactions (including attempted  transactions),  regardless  of  the  amount  of  the  transaction,  to  STRO,  and extend a copy to the Authority for information."
    },
    {
      "section_path": "13.3",
      "heading": "SUSPICIOUS TRANSACTIONS REPORTING",
      "modality": "requirement",
      "text": "An exempt person shall consider if the circumstances are suspicious so as to warrant the filing of an STR and document the basis for its determination, including where  (a) the exempt person is for any reason unable to complete the measures as required by paragraphs 6, 7 and 8; or (b) the  customer  is  reluctant,  unable  or  unwilling  to  provide  any  information requested by the exempt person, decides to withdraw a pending application to establish  business  relations  or  a  pending  transaction,  or  to  terminate  existing business relations."
    },
    {
      "section_path": "13.4",
      "heading": "SUSPICIOUS TRANSACTIONS REPORTING",
      "modality": "permission",
      "text": "Where an exempt person forms a suspicion of money laundering or terrorism financing, and reasonably believes that performing any of the measures as required by paragraphs 6,  7  or  8  will  tip-off  a  customer,  a  natural  person  appointed  to  act  on  behalf  of  the customer, a connected party of the customer or a beneficial owner of the customer, the exemptperson may stop performing those measures."
    },
    {
      "section_path": "13.4",
      "heading": "SUSPICIOUS TRANSACTIONS REPORTING",
      "modality": "requirement",
      "text": "The exempt person shall document the basis for its assessment and file an STR. 5  Please note in particular section 48 of the CDSA on tipping-off."
    },
    {
      "section_path": "14.1",
      "heading": "INTERNAL POLICIES, COMPLIANCE, AUDIT AND TRAINING",
      "modality": "requirement",
      "text": "An exempt person shall develop and implement adequate internal policies, procedures and controls, taking into consideration its money laundering and terrorism financing risks and the size of its business, to help prevent money laundering and terrorism financing and communicate these to its employees."
    },
    {
      "section_path": "14.2",
      "heading": "INTERNAL POLICIES, COMPLIANCE, AUDIT AND TRAINING",
      "modality": "requirement",
      "text": "The policies, procedures and controls shall meet all requirements of this Notice."
    },
    {
      "section_path": "14.3",
      "heading": null,
      "modality": "requirement",
      "text": "An exempt person shall develop appropriate compliance management arrangements, including at least, the appointment of an AML/CFT compliance officer, at the management level."
    },
    {
      "section_path": "14.4",
      "heading": null,
      "modality": "requirement",
      "text": "An exempt person shall ensure that the AML/CFT compliance officer, as well as any other persons appointed to assist him, is suitably qualified and, has adequate resources and timely access to all customer records and other relevant information which he requires to discharge his functions."
    },
    {
      "section_path": "14.5",
      "heading": null,
      "modality": "requirement",
      "text": "An  exempt person shall maintain an audit function that is adequately resourced and independent, and that is able to regularly assess the effectiveness of the exempt person's internal policies, procedures and controls, and its compliance with regulatory requirements."
    },
    {
      "section_path": "14.6",
      "heading": null,
      "modality": "requirement",
      "text": "An exempt person shall have in place screening procedures to ensure high standards when hiring employees and appointing officers."
    },
    {
      "section_path": "14.7",
      "heading": null,
      "modality": "requirement",
      "text": "An  exempt  person  shall  take  all  appropriate  steps  to  ensure  that  its  employees  and officers (whether in Singapore or elsewhere) are regularly and appropriately trained on  (a) AML/CFT laws and regulations, and in particular, CDD measures, detecting and reporting of suspicious transactions; (b) prevailing techniques, methods and trends in money laundering and terrorism financing; and (c) the exempt person's internal policies, procedures and controls on AML/CFT and the  roles  and  responsibilities  of  employees  and  officers  in  combating  money laundering and terrorism financing."
    }
  ],
